THR = float(HG.threshold_ani.iloc[0]); MIN_BLOCK = int(os.environ.get('ATLAS_MIN_BLOCK', '10000')); SW_TOL = int(os.environ.get('ATLAS_SW_TOL', '10000'))
L = []; P = L.append
def md(df): return df.to_markdown(index=False) if hasattr(df, 'to_markdown') else df.to_string(index=False)
def tbl(df):
    cols = list(df.columns); out = ['| ' + ' | '.join(map(str, cols)) + ' |', '|' + '---|' * len(cols)]
    for r in df.itertuples(index=False): out.append('| ' + ' | '.join('' if (isinstance(v, float) and np.isnan(v)) else str(v) for v in r) + ' |')
    return '\n'.join(out)
r2 = E[E.set == 'HPRC_R2']
P('# Allele catalogue v0.1 - QC report\n')
P('Generated by `pipeline/catalogue_10_qc.py` from the release tables in this directory. All numbers below are computed from those files.\n')
P('## 1. Inputs and windows\n')
g = E.groupby('set').agg(ends=('end_id', 'size'), samples=('sample', 'nunique'), full_100kb=('window_len', lambda x: int((x >= C.WINDOW).sum())), extended=('window_len', lambda x: int((x > C.WINDOW).sum())),
                         median_telo_len=('telo_len', 'median')).reset_index()
P(tbl(g)); P('')
WW = rd(f'{C.WIN}/ends_windows.tsv'); n_reuse = int(((WW.set == 'HPRC_R2') & (WW.window_source == 'r2_100k')).sum()); n_fetch = int(((WW.set == 'HPRC_R2') & (WW.window_source == 'fetch')).sum())
P(f"Release 2 windows reused from the earlier 100 kb fetch: {n_reuse}; "
  f"range-read for this release: {n_fetch}. "
  f"Release 2 ends shorter than 100 kb (whole contig used): {int((r2.window_len < C.WINDOW).sum())}.\n")
P('## 2. Home-arm assignment\n')
P(tbl(E.groupby(['set', 'arm_source', 'arm_confidence']).size().rename('ends').reset_index())); P('')
P('Calibration on named Release 2 tips (probe rule: 1,000 random named tips; mosaic rule: all named tips). Group = catalogue arm '
  '(acroP = 13p/14p/15p/21p/22p, PAR1 = Xp/Yp, PAR2 = Xq/Yq).\n')
