c2 = CAL[CAL.confidence.isin(['high', 'medium', 'mosaic_call_in_pooled_group', 'mosaic_call_other_arms'])].copy()
lab = {'high': 'two probes agree', 'medium': 'one informative probe', 'mosaic_call_in_pooled_group': 'mosaic rule, pooled group', 'mosaic_call_other_arms': 'mosaic rule, other arms'}
y = np.arange(len(c2))
ax.barh(y + 0.18, c2.accuracy_group, 0.36, color=BLUE, label='catalogue arm (group)'); ax.barh(y - 0.18, c2.accuracy_arm, 0.36, color=GREY, label='exact arm')
ax.set_yticks(y, [f"{lab[c]} (n={n})" for c, n in zip(c2.confidence, c2.n)]); ax.set_xlim(0, 1.05); ax.set_xlabel('fraction of named tips assigned correctly')
ax.set_title('Probe arm calls are exact at group level', loc='left', x=-0.55); ax.legend(frameon=False, loc='upper center', bbox_to_anchor=(0.3, -0.28), ncol=2)
fig.tight_layout(); fig.savefig(f'{C.FIGQC}/arm_inference_calibration.png'); plt.close(fig)
P('![arm inference](../../figures/qc/arm_inference_calibration.png)\n')
P('## 3. Boundary-anchored states and concordance with earlier calls\n')
