blen = (raw.sub_end - raw.sub_start)
P(f"Raw blocks: {len(raw)} over {raw.end_id.nunique()} ends; base-level switch refinement for "
  f"{int((raw.next_switch_res == 'base').sum())} of {int(raw.next_switch_res.notna().sum())} switches. Core blocks (blocks < {MIN_BLOCK} bp dropped): {len(core)}.\n")
