fsw = []
for (arm, st), g in SMf[SMf.switches.notna() & (SMf.switches.astype(str) != '')].groupby(['arm', 'structure']):
    v = g.switches.astype(str).str.split(',').str[0].astype(float).values
    if len(v) > 1:
        dd = np.abs(v[:, None] - v[None, :])[np.triu_indices(len(v), 1)]; fsw.append(dd)
fsw = np.concatenate(fsw) if fsw else np.zeros(0)
fig, axs = plt.subplots(1, 2, figsize=(6.8, 2.4))
ax = axs[0]; ax.hist(np.clip(blen, 0, 100000) / 1000, bins=100, color=GREY); ax.axvline(MIN_BLOCK / 1000, color=ORANGE, lw=1)
ax.set_yscale('log'); ax.set_xlabel('raw block length (kb)'); ax.set_ylabel('blocks'); ax.set_title(f'Blocks < {MIN_BLOCK // 1000} kb are dropped from core structures')
ax = axs[1]; ax.hist(np.clip(fsw, 0, 60000) / 1000, bins=120, color=GREY); ax.axvline(SW_TOL / 1000, color=ORANGE, lw=1)
ax.set_yscale('log'); ax.set_xlabel('|difference| of first switch, same structure (kb)'); ax.set_ylabel('end pairs')
ax.set_title(f'Switch tolerance {SW_TOL // 1000} kb'); fig.tight_layout(); fig.savefig(f'{C.FIGQC}/structure_thresholds.png'); plt.close(fig)
P(f"Pairs of full-length defining ends with the same core structure: {len(fsw)}; first-switch difference <= 1 kb: {int((fsw <= 1000).sum())} "
  f"({(fsw <= 1000).mean():.3f}), <= {SW_TOL} bp: {int((fsw <= SW_TOL).sum())} ({(fsw <= SW_TOL).mean():.3f}).\n")
P('![structure thresholds](../../figures/qc/structure_thresholds.png)\n')
# allele count sensitivity to tolerance (recomputed here; complete linkage, Chebyshev)
from scipy.cluster.hierarchy import linkage, fcluster
sens = []
for tol in (2000, 5000, 10000, 20000):
    n = 0
    for (arm, st), g in SMf.groupby(['arm', 'structure']):
        sw = g.switches.fillna('').astype(str)
        X = np.array([[float(v) for v in s.split(',')] if s else [] for s in sw], dtype=object)
        k = len(X[0]) if len(X) else 0
        if k == 0 or len(g) == 1: n += 1; continue
        X = np.array([list(r) for r in X], float)
        n += len(set(fcluster(linkage(X, 'complete', metric='chebyshev'), t=tol, criterion='distance')))
    sens.append(dict(switch_tolerance_bp=tol, structural_alleles=n))
P('Structural allele count vs switch tolerance (same definition set):\n'); P(tbl(pd.DataFrame(sens))); P('')
P('## 5. Haplogroup threshold\n')
h = HH.set_index('ani_bin'); tot = h.sum(1)
